mapper.select:
select id, name, room, begin_date as beginDate, end_date as endDate, master_id as masterId, subject, create_time as createTime, update_time as updateTime from clazz


        name like concat('%',#{name},'%')


        and begin_date between #{begin} and #{end}


order by update_time desc
limit #{start}, #{pageSize}

select count(*) from clazz


        name like concat('%',#{name},'%')


        and begin_date between #{begin} and #{end}
